MAKE CODE: Blink without delay
language arduino
// Blink the built-in LED (pin 13) every 500ms without using delay().
// Uses millis() to track elapsed time and toggle the LED when 500ms have passed.

const int ledPin = 13;          // The built-in LED is on pin 13
unsigned long previousMillis = 0; // Stores the last time the LED was toggled
const long interval = 500;      // Interval in milliseconds (0.5 seconds)
int ledState = LOW;             // Current state of the LED

void setup() {
  pinMode(ledPin, OUTPUT);    // Initialize the LED pin as an output
}

void loop() {
  unsigned long currentMillis = millis(); // Get the current time

  // Check if the interval has passed since the last toggle
  if (currentMillis - previousMillis >= interval) {
    previousMillis = currentMillis;       // Update the last time the LED was toggled
    ledState = !ledState;                 // Toggle the LED state (HIGH to LOW or LOW to HIGH)
    digitalWrite(ledPin, ledState);       // Set the LED to the new state
  }
  // The loop continues without blocking, allowing other code to run
}
END

MAKE CODE: Stepper A4988 800 steps
language arduino
// Stepper motor on A4988 driver: moves 800 steps forward and back repeatedly.
// Wiring: STEP -> pin 3, DIR -> pin 2.
// The A4988 driver must be powered (VMOT) and current limited (Vref) before running.
// This sketch uses the AccelStepper library for smooth acceleration.
// Steps per turn depends on the motor (e.g., 200 steps/rev for 1.8 deg) and microstepping.
// 800 steps = 4 full turns for a 200-step motor at 1/1 microstepping.

#include <AccelStepper.h>

// Define pins
const int stepPin = 3;
const int dirPin = 2;

// Configuration
const long stepsPerMove = 800; // Number of steps to move forward/back
const long maxSpeed = 1000;    // Steps per second
const long acceleration = 500; // Steps per second squared

// Create an instance of AccelStepper in DRIVER mode
// DRIVER mode requires separate STEP and DIR pins
AccelStepper stepper(AccelStepper::DRIVER, stepPin, dirPin);

void setup() {
  // Initialize the stepper
  stepper.setMaxSpeed(maxSpeed);
  stepper.setAcceleration(acceleration);
  // Start at position 0
  stepper.moveTo(0);
}

void loop() {
  // Run the stepper
  stepper.run();

  // Check if we have reached the target position
  if (stepper.distanceToGo() == 0) {
    // If we are at 0, move forward 800 steps
    if (stepper.currentPosition() == 0) {
      stepper.moveTo(stepsPerMove);
    } 
    // If we are at 800, move back to 0
    else if (stepper.currentPosition() == stepsPerMove) {
      stepper.moveTo(0);
    }
  }
}
END

MAKE CODE: Motor Start/Stop Seal-in
language arduino
// P1AM-100: Motor start/stop with seal-in on Productivity1000 I/O modules.
// Slot 1: Discrete input module.
//   Channel 1: Start button (Normally Open).
//   Channel 2: Stop button (Normally Closed).
// Slot 2: Discrete output module.
//   Channel 1: Motor contactor coil.
#include <P1AM.h>

const int inSlot = 1;
const int outSlot = 2;
bool running = false;

void setup() {
  Serial.begin(115200);
  while (!P1.init()) {
    ; // Wait for modules to initialize
  }
}

void loop() {
  // Read inputs: Start (NO) is true when pressed.
  // Stop (NC) is true when NOT pressed (circuit closed).
  bool startPressed = P1.readDiscrete(inSlot, 1);
  bool stopPressed = !P1.readDiscrete(inSlot, 2); // Invert NC logic: false means pressed/open

  // Seal-in logic:
  // If Start is pressed OR currently running, AND Stop is not pressed, then run.
  running = (startPressed || running) && !stopPressed;

  // Write outputs:
  // Channel 1: Motor contactor (On if running)
  P1.writeDiscrete(running, outSlot, 1);
}
END

MAKE CODE: Average temperature from CSV
python
import csv
import sys

def main():
    if len(sys.argv) < 2:
        print("usage: python3 avg_temp.py readings.csv")
        return

    temps = []
    try:
        with open(sys.argv[1], newline='') as f:
            reader = csv.DictReader(f)
            for row in reader:
                try:
                    # Extract the 'temp' column and convert to float
                    val = float(row['temp'])
                    temps.append(val)
                except (ValueError, KeyError):
                    # Skip rows with missing or non-numeric temp data
                    continue

        if not temps:
            print("No valid temperature data found.")
            return

        average = sum(temps) / len(temps)
        print(f"Average temperature: {average}")

    except FileNotFoundError:
        print(f"Error: File '{sys.argv[1]}' not found.")
    except Exception as e:
        print(f"Error processing file: {e}")

if __name__ == "__main__":
    main()
END

