PROGRAM TankFill
VAR
    LowFloat : BOOL;
    HighFloat : BOOL;
    FillValve : BOOL;
END_VAR

// Tank Fill Control Logic
// Open FillValve when LowFloat is TRUE and HighFloat is FALSE.
// Close FillValve when HighFloat is TRUE.
