MAKE CODE: Tank Fill Control
language st
// Tank Fill Control in Structured Text
// Inputs:
//   LowFloat  - Input bit, TRUE when water is low (valve should open)
//   HighFloat - Input bit, TRUE when water is high (valve should close)
// Output:
//   FillValve - Output bit, TRUE to open the fill valve
// Logic:
//   Open FillValve when LowFloat is TRUE and HighFloat is FALSE.
//   Close FillValve when HighFloat is TRUE.
//   This assumes a fail-safe or latching logic is not required beyond the immediate state.
//   If HighFloat is active, the valve closes regardless of LowFloat.
//   If LowFloat is active and HighFloat is inactive, the valve opens.

IF HighFloat THEN
    FillValve := FALSE;
ELSIF LowFloat THEN
    FillValve := TRUE;
ELSE
    // If neither is active, keep the valve in its last state or close it.
    // For safety, we usually default to closed if no command is given,
    // but a simple state machine might be better for latching.
    // Here we assume direct control: if LowFloat is true, open.
    // If the tank is between levels (neither true), we keep it closed to prevent overflow if HighFloat just tripped.
    // However, a more robust "latching" logic is often preferred:
    // FillValve := FillValve OR LowFloat;
    // FillValve := FillValve AND NOT HighFloat;
    // Let's use the latching logic for a standard tank fill sequence.
    FillValve := FillValve OR LowFloat;
    FillValve := FillValve AND NOT HighFloat;
END_IF;
END
